package main

import (
	"fmt"
	"strings"
)

// renderDoc renders docs/schema.md: the record contract, one row per key.
func renderDoc(s *schema) []byte {
	var b strings.Builder
	fmt.Fprintf(&b, `---
type: API
title: audit — schema v%[1]s
description: The audit record contract, key by key, generated from schema/v1.yaml.
resource: github.com/krateo-platformops/audit
tags: [library, audit, schema]
timestamp: %[2]s
---

<!-- Generated by internal/schemagen from schema/v1.yaml. DO NOT EDIT. -->

# Audit schema v%[1]s

Every audit record is an OTLP LogRecord with EventName %[3]s and the
attributes below, and no others (the closed set). Go writers spell keys
through the generated `+"`audit.Key*`"+` constants and test their records with
`+"`audit.Check`"+` and `+"`audittest`"+`; other writers use `+"`cmd/auditschema`"+`.

## Writers

| writer | code | who |
|---|---|---|
`, s.SchemaVersion, s.Updated, "`"+s.EventName+"`")
	for _, w := range s.Writers {
		fmt.Fprintf(&b, "| `%s` | %s | %s |\n", w.ID, w.Code, cell(w.Description))
	}

	b.WriteString(`
## Levels

- **R**: required. **R (mark)**: required, or omitted and named in
  ` + "`krateo.audit.incomplete`" + ` when the writer cannot establish it.
- **C: when**: required when *when* holds. **[checked]**: ` + "`Check`" + ` evaluates the
  condition on the record. Without it, the condition is not visible on the
  record and ` + "`Check`" + ` treats the key as optional, unless it is **(mark)**: then
  it must be present or marked.
- **O**: optional. **NE**: not established by this writer, never written.
  **—**: does not apply.

## Keys

`)
	b.WriteString("| key | type | semconv |")
	for _, w := range s.Writers {
		fmt.Fprintf(&b, " %s |", w.Code)
	}
	b.WriteString(" description |\n|---|---|---|")
	for range s.Writers {
		b.WriteString("---|")
	}
	b.WriteString("---|\n")
	for _, k := range s.Keys {
		if k.ReplacedBy != "" {
			continue
		}
		fmt.Fprintf(&b, "| `%s` | %s | %s |", k.Name, cell(k.Type), k.Semconv)
		for _, w := range s.Writers {
			fmt.Fprintf(&b, " %s |", levelCell(k.Writers[w.ID]))
		}
		fmt.Fprintf(&b, " %s |\n", cell(keyNotes(k)))
	}

	fmt.Fprintf(&b, `
## The target rule

Every record names its target: `+"`%s`"+` (a Kubernetes object) or `+"`%s`"+`
(an external endpoint). Marker `+"`%s`"+`.

| writer | targets |
|---|---|
`, s.Target.Keys[0], s.Target.Keys[1], s.Target.Marker)
	for _, w := range s.Writers {
		fmt.Fprintf(&b, "| `%s` | %s |\n", w.ID, strings.ReplaceAll(s.Target.Writers[w.ID], "_", " "))
	}

	b.WriteString("\n## Conditions `Check` evaluates\n\n")
	for _, c := range s.Conditions {
		fmt.Fprintf(&b, "- `%s`: %s\n", c.ID, c.Description)
	}

	b.WriteString(`
## v0.3 keys (migration window W1)

Written side by side with their replacement by v0.4.x, with the same value,
and removed in v0.5.0. Readers ` + "`coalesce`" + ` the two until the last row without
` + "`krateo.audit.schema_version`" + ` expires.

| v0.3 key | replaced by |
|---|---|
`)
	for _, k := range s.Keys {
		if k.ReplacedBy != "" {
			fmt.Fprintf(&b, "| `%s` | `%s` |\n", k.Name, k.ReplacedBy)
		}
	}

	b.WriteString("\n## Where each writer's records land\n\n| instrumentation scope | writer | who |\n|---|---|---|\n")
	for _, p := range s.Populations {
		fmt.Fprintf(&b, "| `%s` | `%s` | %s |\n", p.Scope, p.Writer, cell(p.Who))
	}
	for _, p := range s.LegacyControls {
		fmt.Fprintf(&b, "| `%s` | `%s` | %s (pre-schema, the positive control) |\n", p.Scope, p.Writer, cell(p.Who))
	}
	return []byte(b.String())
}

func levelCell(r requirement) string {
	mark := ""
	if r.Markable {
		mark = " (mark)"
	}
	switch r.Level {
	case "required":
		return "R" + mark
	case "conditional":
		checked := ""
		if r.Check != "" {
			checked = " [checked]"
		}
		return "C: " + cell(r.When) + checked + mark
	case "optional":
		return "O"
	case "not_established":
		return "NE"
	}
	return "—"
}

func keyNotes(k key) string {
	var notes []string
	if len(k.Values) > 0 {
		notes = append(notes, "One of `"+strings.Join(k.Values, "`, `")+"`.")
	}
	if k.Marker != "" {
		notes = append(notes, "Marker `"+k.Marker+"`.")
	}
	if k.Identity {
		notes = append(notes, "**Identity.**")
	}
	if k.Asserted {
		notes = append(notes, "**Asserted** (client-chosen).")
	}
	return k.Description + " " + strings.Join(notes, " ")
}

func cell(s string) string {
	return strings.TrimSpace(strings.NewReplacer("|", `\|`, "<", "&lt;", ">", "&gt;").Replace(s))
}
